&reftitle.description;
#[\Deprecated(since: '8.1', message: 'use IntlDateFormatter::format() instead')] stringfalsestrftime stringformat intnulltimestamp&null;
Formatta l'ora e/o la data in base alle impostazioni locali. I nomi dei mesi e dei giorni della settimana e le altre stringhe che dipendono dalla lingua rispettano le impostazioni locali correnti impostate con setlocale.
Non tutti gli specificatori di conversione potrebbero essere supportati dalla libreria C in uso, nel qual caso non saranno supportati nemmeno dalla strftime di PHP. Inoltre, non tutte le piattaforme supportano i timestamp negativi, quindi l'intervallo di date potrebbe essere limitato a date non precedenti all'epoca Unix. Ciò significa che %e, %T, %R e %D (e forse altri), così come le date precedenti al Jan 1, 1970, non funzioneranno su Windows, su alcune distribuzioni Linux e su pochi altri sistemi operativi. Per i sistemi Windows, una panoramica completa degli specificatori di conversione supportati è disponibile su MSDN. Usare invece il metodo IntlDateFormatter::format.

  &reftitle.examples;


   Questo esempio funziona se nel sistema sono installate le rispettive
   impostazioni locali.

    Esempi di strftime con diverse impostazioni locali


<?php
setlocale(LC_TIME, "C");
echo strftime("%A");
setlocale(LC_TIME, "fi_FI");
echo strftime(" in finlandese è %A,");
setlocale(LC_TIME, "fr_FR");
echo strftime(" in francese %A e");
setlocale(LC_TIME, "de_DE");
echo strftime(" in tedesco %A.\n");







    Esempio del numero di settimana ISO 8601:1988


<?php
/*     Dicembre 2002 / Gennaio 2003
Sett.  Lu  Ma  Me  Gi  Ve  Sa  Do
----- ----------------------------
51     16  17  18  19  20  21  22
52     23  24  25  26  27  28  29
1      30  31   1   2   3   4   5
2       6   7   8   9  10  11  12
3      13  14  15  16  17  18  19   */

// Visualizza: 12/28/2002 - %V,%G,%Y = 52,2002,2002
echo "12/28/2002 - %V,%G,%Y = " . strftime("%V,%G,%Y", strtotime("12/28/2002")) . "\n";

// Visualizza: 12/30/2002 - %V,%G,%Y = 1,2003,2002
echo "12/30/2002 - %V,%G,%Y = " . strftime("%V,%G,%Y", strtotime("12/30/2002")) . "\n";

// Visualizza: 1/3/2003 - %V,%G,%Y = 1,2003,2003
echo "1/3/2003 - %V,%G,%Y = " . strftime("%V,%G,%Y",strtotime("1/3/2003")) . "\n";

// Visualizza: 1/10/2003 - %V,%G,%Y = 2,2003,2003
echo "1/10/2003 - %V,%G,%Y = " . strftime("%V,%G,%Y",strtotime("1/10/2003")) . "\n";



/*     Dicembre 2004 / Gennaio 2005
Sett.  Lu  Ma  Me  Gi  Ve  Sa  Do
----- ----------------------------
51     13  14  15  16  17  18  19
52     20  21  22  23  24  25  26
53     27  28  29  30  31   1   2
1       3   4   5   6   7   8   9
2      10  11  12  13  14  15  16   */

// Visualizza: 12/23/2004 - %V,%G,%Y = 52,2004,2004
echo "12/23/2004 - %V,%G,%Y = " . strftime("%V,%G,%Y",strtotime("12/23/2004")) . "\n";

// Visualizza: 12/31/2004 - %V,%G,%Y = 53,2004,2004
echo "12/31/2004 - %V,%G,%Y = " . strftime("%V,%G,%Y",strtotime("12/31/2004")) . "\n";

// Visualizza: 1/2/2005 - %V,%G,%Y = 53,2004,2005
echo "1/2/2005 - %V,%G,%Y = " . strftime("%V,%G,%Y",strtotime("1/2/2005")) . "\n";

// Visualizza: 1/3/2005 - %V,%G,%Y = 1,2005,2005
echo "1/3/2005 - %V,%G,%Y = " . strftime("%V,%G,%Y",strtotime("1/3/2005")) . "\n";







    Esempio compatibile con più piattaforme che usa il modificatore %e


<?php

// 1 gen: risulta in: '%e%1%' (%%, e, %%, %e, %%)
$format = '%%e%%%e%%';

// Su Windows, trova e sostituisce il modificatore %e
// in modo corretto
if (strtoupper(substr(PHP_OS, 0, 3)) == 'WIN') {
    $format = preg_replace('#(?<!%)((?:%%)*)%e#', '\1%#d', $format);
}

echo strftime($format);







    Visualizzare tutti i formati noti e sconosciuti


<?php

// Descrive i formati
$strftimeFormats = array(
    'A' => 'Rappresentazione testuale completa del giorno',
    'B' => 'Nome completo del mese, in base alle impostazioni locali',
    'C' => 'Rappresentazione a due cifre del secolo (anno diviso per 100, troncato a intero)',
    'D' => 'Come "%m/%d/%y"',
    'E' => '',
    'F' => 'Come "%Y-%m-%d"',
    'G' => 'La versione completa a quattro cifre di %g',
    'H' => 'Rappresentazione a due cifre dell\'ora nel formato 24 ore',
    'I' => 'Rappresentazione a due cifre dell\'ora nel formato 12 ore',
    'J' => '',
    'K' => '',
    'L' => '',
    'M' => 'Rappresentazione a due cifre del minuto',
    'N' => '',
    'O' => '',
    'P' => '"am" o "pm" in minuscolo in base all\'ora indicata',
    'Q' => '',
    'R' => 'Come "%H:%M"',
    'S' => 'Rappresentazione a due cifre del secondo',
    'T' => 'Come "%H:%M:%S"',
    'U' => 'Numero della settimana dell\'anno indicato, a partire dalla prima domenica come prima settimana',
    'V' => 'Numero della settimana ISO-8601:1988 dell\'anno indicato, a partire dalla prima settimana dell\'anno con almeno 4 giorni feriali, con il lunedì come inizio della settimana',
    'W' => 'Rappresentazione numerica della settimana dell\'anno, a partire dal primo lunedì come prima settimana',
    'X' => 'Rappresentazione preferita dell\'ora in base alle impostazioni locali, senza la data',
    'Y' => 'Rappresentazione a quattro cifre dell\'anno',
    'Z' => 'L\'opzione scostamento/abbreviazione del fuso orario NON fornita da %z (dipende dal sistema operativo)',
    'a' => 'Rappresentazione testuale abbreviata del giorno',
    'b' => 'Nome abbreviato del mese, in base alle impostazioni locali',
    'c' => 'Data e ora preferite in base alle impostazioni locali',
    'd' => 'Giorno del mese a due cifre (con zeri iniziali)',
    'e' => 'Giorno del mese, con uno spazio prima delle cifre singole',
    'f' => '',
    'g' => 'Rappresentazione a due cifre dell\'anno secondo gli standard ISO-8601:1988 (vedere %V)',
    'h' => 'Nome abbreviato del mese, in base alle impostazioni locali (un alias di %b)',
    'i' => '',
    'j' => 'Giorno dell\'anno, a 3 cifre con zeri iniziali',
    'k' => 'Ora nel formato 24 ore, con uno spazio prima delle cifre singole',
    'l' => 'Ora nel formato 12 ore, con uno spazio prima delle cifre singole',
    'm' => 'Rappresentazione a due cifre del mese',
    'n' => 'Un carattere di nuova riga ("\n")',
    'o' => '',
    'p' => '"AM" o "PM" in MAIUSCOLO in base all\'ora indicata',
    'q' => '',
    'r' => 'Come "%I:%M:%S %p"',
    's' => 'Timestamp dell\'epoca Unix',
    't' => 'Un carattere di tabulazione ("\t")',
    'u' => 'Rappresentazione numerica ISO-8601 del giorno della settimana',
    'v' => '',
    'w' => 'Rappresentazione numerica del giorno della settimana',
    'x' => 'Rappresentazione preferita della data in base alle impostazioni locali, senza l\'ora',
    'y' => 'Rappresentazione a due cifre dell\'anno',
    'z' => 'Lo scostamento del fuso orario da UTC oppure l\'abbreviazione (dipende dal sistema operativo)',
    '%' => 'Un carattere percentuale letterale ("%")',
);

// Risultati
$strftimeValues = array();

// Valuta i formati sopprimendo eventuali errori
foreach ($strftimeFormats as $format => $description) {
    if (false !== ($value = @strftime("%{$format}"))) {
        $strftimeValues[$format] = $value;
    }
}

// Trova il valore più lungo
$maxValueLength = 2 + max(array_map('strlen', $strftimeValues));

// Riporta i formati noti
foreach ($strftimeValues as $format => $value) {
    echo "Formato noto        : '{$format}' = ", str_pad("'{$value}'", $maxValueLength), " ( {$strftimeFormats[$format]} )\n";
}

// Riporta i formati sconosciuti
foreach (array_diff_key($strftimeFormats, $strftimeValues) as $format => $description) {
    echo "Formato sconosciuto : '{$format}'   ", str_pad(' ', $maxValueLength), ($description ? " ( {$description} )" : ''), "\n";
}


    &example.outputs.similar;


